detail.command:
set -e
git checkout --theirs -- src/ui/ui.css
cat >> src/ui/ui.css <<'EOF'
.cpa-leaderboard {
  display: flex;
  justify-content: center;
}
.cpa-leaderboard .leaderboard {
  width: min(880px, 100%);
  max-height: none;
}
.cpa-note {
  margin: 0 0 18px;
  color: #91a7b9;
  font-size: 13px;
  font-weight: 750;
  letter-spacing: 0.04em;
}
EOF
echo '=== markers left (expect 0 0) ==='
grep -c '<<<<<<<\|=======\|>>>>>>>' src/ui/index.ts src/ui/ui.css || true
echo '=== repo-wide markers ==='
grep -rn '^<<<<<<< \|^>>>>>>> ' src/ || echo none
echo '=== commit ==='
git add -A && git commit --no-edit -q && git log --oneline -2
git status --short | head -5
